exercises.starterCode:
// Strings hold text data. Use double quotes, single quotes, or backticks.

// 1. A greeting using double quotes

// 2. A programming language using single quotes

// 3. A welcome message using backticks

// 4. An empty string

// 5. A full name with a space

exercises.solution:
const greeting = "Hello, world!";
const language = 'JavaScript';
const message = `Welcome back`;
const empty = "";
const fullName = "Jane Doe";

exercises.testRunner:
(code) => {
  const r = new Function(code + '; return { greeting, language, message, empty, fullName };')();
  return [
    { pass: r.greeting === 'Hello, world!', description: 'greeting is "Hello, world!"', got: String(r.greeting) },
    { pass: r.language === 'JavaScript', description: 'language is "JavaScript"', got: String(r.language) },
    { pass: r.message === 'Welcome back', description: 'message is "Welcome back"', got: String(r.message) },
    { pass: r.empty === '', description: 'empty is "" (empty string)', got: JSON.stringify(r.empty) },
    { pass: r.fullName === 'Jane Doe', description: 'fullName is "Jane Doe"', got: String(r.fullName) },
    { pass: typeof r.greeting === 'string', description: 'All values are strings', got: typeof r.greeting }
  ];
}

exercises.starterCode:
// Numbers include integers, decimals, and negatives.
// Numbers do NOT use quotes.

// 1. A test score (integer)

// 2. A price with cents (decimal)

// 3. A cold temperature (negative)

// 4. The number zero

// 5. A large population count

exercises.solution:
const score = 95;
const price = 19.99;
const temperature = -5;
const zero = 0;
const population = 7900000000;

exercises.testRunner:
(code) => {
  const r = new Function(code + '; return { score, price, temperature, zero, population };')();
  return [
    { pass: r.score === 95, description: 'score is 95', got: String(r.score) },
    { pass: Math.abs(r.price - 19.99) < 0.001, description: 'price is 19.99', got: String(r.price) },
    { pass: r.temperature === -5, description: 'temperature is -5', got: String(r.temperature) },
    { pass: r.zero === 0, description: 'zero is 0', got: String(r.zero) },
    { pass: r.population === 7900000000, description: 'population is 7900000000', got: String(r.population) }
  ];
}

