    { pass: r.isVisible === true, description: 'isVisible is true', got: String(r.isVisible) },
    { pass: r.MAX_RETRIES === 3, description: 'MAX_RETRIES is 3', got: String(r.MAX_RETRIES) },
    { pass: JSON.stringify(r.shoppingCart) === '[]', description: 'shoppingCart is []', got: JSON.stringify(r.shoppingCart) },
