    { pass: r.defaultColor === 'blue', description: 'defaultColor is "blue"', got: String(r.defaultColor) }
  ];
}

exercises.starterCode:
// Change array elements: arrayName[index] = newValue;

const colors = ["red", "green", "blue", "yellow", "purple"];

// 1. Change index 0 to "crimson"

// 2. Change index 2 to "navy"

// 3. Change index 4 to "violet"

// 4. Change index 1 to "lime"

// 5. Change index 3 to "gold"

exercises.solution:
const colors = ["red", "green", "blue", "yellow", "purple"];
colors[0] = "crimson";
colors[2] = "navy";
colors[4] = "violet";
colors[1] = "lime";
colors[3] = "gold";

exercises.testRunner:
(code) => {
