    { pass: fn(0,10,2) === '0 2 4 6 8 10 ', description: 'buildRange(0,10,2) returns "0 2 4 6 8 10 "', got: String(fn(0,10,2)) },
    { pass: fn(10,50,10) === '10 20 30 40 50 ', description: 'buildRange(10,50,10) returns "10 20 30 40 50 "', got: String(fn(10,50,10)) }
  ];
}

