exercises.solution:
function isPalindrome(str) {
  let lower = str.toLowerCase();
  for (let i = 0; i < lower.length / 2; i++) {
    if (lower[i] !== lower[lower.length - 1 - i]) {
      return false;
    }
  }
  return true;
}

