  const r3 = fn([]);
  const r4 = fn([{name:'Eve',score:50},{name:'Frank',score:40}]);
  const r5 = fn([{name:'A',score:100},{name:'B',score:90},{name:'C',score:80},{name:'D',score:70},{name:'E',score:60}]);
  return [
