    { pass: r5.average === 80 && r5.highest === 100 && JSON.stringify(r5.passing) === '["A","B","C","D"]', description: 'summarizeScores with 5 students returns 4 passing', got: JSON.stringify(r5) }
  ];
}

exercises.solution:
function processOrders(orders, status) {
  const filtered = [];
  for (let i = 0; i < orders.length; i++) {
    if (orders[i].status === status) {
      filtered.push(orders[i]);
    }
  }
  const prices = [];
  for (let i = 0; i < filtered.length; i++) {
    prices.push(filtered[i].price);
  }
  let total = 0;
  for (let i = 0; i < prices.length; i++) {
    total += prices[i];
  }
  return total;
}

