// Building objects dynamically:
// 1. Create an empty object with {}
// 2. Use bracket notation to add properties: obj[key] = value
// 3. Bracket notation works with variables, unlike dot notation

function buildObject(keys, values) {
  // Create an empty object
  // Loop through the keys array (use index to access both arrays)
  //   Set obj[keys[i]] = values[i]
  // Return the object
}

exercises.solution:
function buildObject(keys, values) {
  const obj = {};
  for (let i = 0; i < keys.length; i++) {
    obj[keys[i]] = values[i];
  }
  return obj;
}

