function charFrequency(str) {
  const freq = {};
  for (let i = 0; i < str.length; i++) {
    const ch = str[i];
    if (freq[ch] === undefined) {
      freq[ch] = 1;
    } else {
      freq[ch]++;
    }
  }
  return freq;
}

