}

exercises.solution:
function topWords(text, n) {
  var words = text.toLowerCase().split(" ").filter(function(w) { return w.length > 0; });
  var counts = words.reduce(function(acc, w) {
    acc[w] = (acc[w] || 0) + 1;
    return acc;
  }, {});
  return Object.keys(counts)
    .map(function(w) { return { word: w, count: counts[w] }; })
    .sort(function(a, b) { return b.count - a.count; })
    .slice(0, n);
}

