}

exercises.solution:
function analyzeGrades(students) {
  var grades = students.map(function(s) { return s.grade; });
  var sum = grades.reduce(function(acc, g) { return acc + g; }, 0);
  var sorted = grades.slice().sort(function(a, b) { return a - b; });
  var passing = grades.filter(function(g) { return g >= 60; });
  return {
    average: sum / grades.length,
    highest: sorted[sorted.length - 1],
    lowest: sorted[0],
    passing: passing.length,
    failing: grades.length - passing.length
  };
}

