/**
 * Apply a callback to each element and return a new array of results.
 * This is a manual implementation of Array.prototype.map().
 *
 * @param {Array} arr - The input array
 * @param {Function} callback - Function to apply to each element
 * @returns {Array} New array with callback applied to each element
 */
function applyToEach(arr, callback) {

}

exercises.solution:
function applyToEach(arr, callback) {
  var result = [];
  for (var i = 0; i < arr.length; i++) {
    result.push(callback(arr[i], i, arr));
  }
  return result;
}

