  c1.subtract(3);
  var r3 = c1.getResult();
  var r4 = c1.getHistory();
  c1.add(5);
  var r5 = c1.getHistory();
  var h = c1.getHistory();
  h.push('tamper');
  var r6 = c1.getHistory();
