/**
 * @returns {{ isNonEmpty: Function, isInRange: Function, isValidLength: Function }}
 *   isNonEmpty(str) - returns true if str has length > 0 after trimming
 *   isInRange(n, min, max) - returns true if min <= n <= max
 *   isValidLength(str, min, max) - returns true if trimmed string length is between min and max (inclusive)
 */
function createValidator() {

}

exercises.solution:
function createValidator() {
  function trimStr(str) {
    return str.trim();
  }

  function isNonEmpty(str) {
    return trimStr(str).length > 0;
  }

  function isInRange(n, min, max) {
    return n >= min && n <= max;
  }

  function isValidLength(str, min, max) {
    var len = trimStr(str).length;
    return isInRange(len, min, max);
  }

  return {
    isNonEmpty: isNonEmpty,
    isInRange: isInRange,
    isValidLength: isValidLength
  };
}

