exercises.starterCode:
/**
 * @returns {{ addTask: Function, completeTask: Function, getTasks: Function, getPending: Function }}
 *   addTask(name) - adds {name, done: false} to the task list
 *   completeTask(name) - marks the first task with that name as done (no-op if not found)
 *   getTasks() - returns a copy of all tasks
 *   getPending() - returns an array of names of tasks that are not done
 */
function createTaskManager() {

}

exercises.solution:
function createTaskManager() {
  var tasks = [];

  function addTask(name) {
    tasks.push({ name: name, done: false });
  }

  function completeTask(name) {
    for (var i = 0; i < tasks.length; i++) {
      if (tasks[i].name === name && !tasks[i].done) {
        tasks[i].done = true;
        return;
      }
    }
  }

  function getTasks() {
    return tasks.map(function(t) {
      return { name: t.name, done: t.done };
    });
  }

  function getPending() {
    return tasks
      .filter(function(t) { return !t.done; })
      .map(function(t) { return t.name; });
  }

  return {
    addTask: addTask,
    completeTask: completeTask,
    getTasks: getTasks,
    getPending: getPending
  };
}

exercises.testRunner:
(code) => {
  const fn = new Function(code + '; return createTaskManager;')();
  var tm = fn();
  var r1 = tm.getTasks();
  tm.addTask('Write code');
  tm.addTask('Run tests');
  var r2 = tm.getTasks();
  var r3 = tm.getPending();
  tm.completeTask('Write code');
  var r4 = tm.getPending();
  var r5 = tm.getTasks();
  tm.completeTask('not found');
  var r6 = tm.getPending();
  tm.addTask('Deploy');
  var r7 = tm.getPending();
  tm.completeTask('Run tests');
  tm.completeTask('Deploy');
  var r8 = tm.getPending();
