/**
 * A tagged template function that wraps interpolated values in [ ].
 * Called as: highlight`Hello ${name}, you scored ${score}`
 * Returns: "Hello [Alice], you scored [95]"
 *
 * @param {string[]} strings - The static string parts
 * @param {...*} values - The interpolated values
 * @returns {string} Combined string with values wrapped in brackets
 */
const highlight = (strings, ...values) => {

};

exercises.solution:
const highlight = (strings, ...values) => {
  let result = '';
  strings.forEach((str, i) => {
    result += str;
    if (i < values.length) {
      result += '[' + values[i] + ']';
    }
  });
  return result;
};

exercises.testRunner:
(code) => {
  const fn = new Function(code + '; return highlight;')();
