/**
 * Rewrite createTaskManager using all ES6 features:
 *   - const/let, arrow functions, shorthand properties
 *   - Destructuring in callbacks where useful
 *
 * @returns {{ addTask: Function, completeTask: Function, getTasks: Function, getPending: Function }}
 *   addTask(name) - adds {name, done: false}
 *   completeTask(name) - marks first matching undone task as done
 *   getTasks() - returns copy of all tasks
 *   getPending() - returns names of undone tasks
 */
const createStoreES6 = () => {

};

exercises.solution:
const createStoreES6 = () => {
  const tasks = [];

  const addTask = (name) => {
    tasks.push({ name, done: false });
  };

  const completeTask = (name) => {
    const task = tasks.find(({name: n, done}) => n === name && !done);
    if (task) task.done = true;
  };

  const getTasks = () => tasks.map(({name, done}) => ({ name, done }));

  const getPending = () => tasks
    .filter(({done}) => !done)
    .map(({name}) => name);

  return { addTask, completeTask, getTasks, getPending };
};

