/**
 * @param {number} initial - Starting balance (must be >= 0, default 0 if negative)
 * Properties: this._balance (private-style)
 * get balance() - returns current balance
 * deposit(amount) - adds amount if positive
 * withdraw(amount) - subtracts amount if positive and sufficient funds
 */
