}

exercises.solution:
class BankAccount {
  constructor(initial) {
    this._balance = initial >= 0 ? initial : 0;
  }

  get balance() {
    return this._balance;
  }

  deposit(amount) {
    if (amount > 0) {
      this._balance += amount;
    }
  }

  withdraw(amount) {
    if (amount > 0 && amount <= this._balance) {
      this._balance -= amount;
    }
  }
}

