exercises.solution:
class Playlist {
  constructor(name) {
    this.name = name;
    this._songs = [];
    this._currentIndex = 0;
  }

  add(song) {
    this._songs.push(song);
  }

  remove(song) {
    const idx = this._songs.indexOf(song);
    if (idx === -1) return;
    this._songs.splice(idx, 1);
    if (this._songs.length === 0) {
      this._currentIndex = 0;
    } else if (idx < this._currentIndex) {
      this._currentIndex -= 1;
    } else if (this._currentIndex >= this._songs.length) {
      this._currentIndex = 0;
    }
  }

  next() {
    if (this._songs.length === 0) return null;
    this._currentIndex = (this._currentIndex + 1) % this._songs.length;
    return this._songs[this._currentIndex];
  }

  get current() {
    if (this._songs.length === 0) return null;
    return this._songs[this._currentIndex];
  }

  get length() {
    return this._songs.length;
  }
}

