class Logger {
  constructor() {
    this._messages = [];
  }

  log(msg) {
    this._messages.push(msg);
  }

  get messages() {
    return this._messages.slice();
  }
}

class App {
  constructor(name, logger) {
    this.name = name;
    this.logger = logger;
    this.isRunning = false;
  }

  start() {
    this.isRunning = true;
    this.logger.log(this.name + " started");
  }

  stop() {
    this.isRunning = false;
    this.logger.log(this.name + " stopped");
  }
}

