exercises.solution:
class MenuItem {
  constructor(name, price) {
    this.name = name;
    this.price = price;
  }
}

class Order {
  constructor() {
    this._items = [];
  }

  add(item, qty) {
    const existing = this._items.find(e => e.item.name === item.name);
    if (existing) {
      existing.qty += qty;
    } else {
      this._items.push({ item, qty });
    }
  }

  remove(name) {
    const idx = this._items.findIndex(e => e.item.name === name);
    if (idx !== -1) this._items.splice(idx, 1);
  }

  get total() {
    return this._items.reduce((sum, e) => sum + e.item.price * e.qty, 0);
  }

  get itemCount() {
    return this._items.reduce((sum, e) => sum + e.qty, 0);
  }
}

