/**
 * @param {string} jsonString - A string to parse as JSON
 * @returns {{ data: any, error: string|null, attempted: boolean }}
 *   data: the parsed result (or null if parsing failed)
 *   error: the error message (or null if parsing succeeded)
 *   attempted: always true (set in finally)
 */
