/**
 * @param {string} value - A string that may or may not be a valid number
 * @returns {{ value: number|null, status: string }}
 *   If valid: { value: <parsed number>, status: "success" }
 *   If NaN after parsing: { value: null, status: "not a number" }
 *   If any other error: { value: null, status: "error" }
 *
 * Use Number() to parse. If result is NaN, throw new Error("not a number").
 * If the input is not a string, throw new TypeError("expected string").
 */
function parseNumber(value) {

}

exercises.solution:
function parseNumber(value) {
  try {
    if (typeof value !== "string") {
      throw new TypeError("expected string");
    }
    const num = Number(value);
    if (isNaN(num)) {
      throw new Error("not a number");
    }
    return { value: num, status: "success" };
  } catch (error) {
    if (error.message === "not a number") {
      return { value: null, status: "not a number" };
    }
    return { value: null, status: "error" };
  }
}

