/**
 * @param {string} id - The element ID
 * @param {string} action - "add", "remove", or "toggle"
 * @param {string} className - The class name to modify
 * @returns {boolean} Whether the element has the class after the operation
 */
function modifyClass(id, action, className) {

}

exercises.solution:
function modifyClass(id, action, className) {
  const element = document.getElementById(id);
  if (action === "add") element.classList.add(className);
  else if (action === "remove") element.classList.remove(className);
  else if (action === "toggle") element.classList.toggle(className);
  return element.classList.contains(className);
}

