exercises.solution:
function setAttr(id, attr, value) {
  const element = document.getElementById(id);
  if (element) {
    element.setAttribute(attr, value);
  }
}

function getAttr(id, attr) {
  const element = document.getElementById(id);
  if (!element) return null;
  return element.getAttribute(attr);
}

