/**
 * @param {string[]} items - Array of strings for list items
 * @param {string} containerId - ID of the container to append the list to
 * @returns {HTMLUListElement} The created <ul> element
 */
function buildList(items, containerId) {

}

exercises.solution:
function buildList(items, containerId) {
  const ul = document.createElement("ul");
  items.forEach(item => {
    const li = document.createElement("li");
    li.textContent = item;
    ul.appendChild(li);
  });
  document.getElementById(containerId).appendChild(ul);
  return ul;
}

