/**
 * @param {string} containerId - ID of the container holding buttons
 * @param {string} outputId - ID of the element to display results
 * When any button inside the container is clicked, set the output text to:
 * "Clicked: <button text>"
 */
function setupClickReporter(containerId, outputId) {

}

exercises.solution:
function setupClickReporter(containerId, outputId) {
  const container = document.getElementById(containerId);
  const output = document.getElementById(outputId);
  const buttons = container.querySelectorAll("button");
  buttons.forEach(button => {
    button.addEventListener("click", (event) => {
      output.textContent = "Clicked: " + event.target.textContent;
    });
  });
}

