}

exercises.solution:
function promisify(callbackFn) {
  return function(value) {
    return new Promise(function(resolve, reject) {
      callbackFn(value, function(error, result) {
        if (error) {
          reject(error);
        } else {
          resolve(result);
        }
      });
    });
  };
}

