exercises.solution:
function generateReportCards(students) {
  return students.map(function({ name, scores }) {
    const average = Math.round(scores.reduce(function(sum, s) { return sum + s; }, 0) / scores.length * 10) / 10;
    let letterGrade;
    if (average >= 90) letterGrade = "A";
    else if (average >= 80) letterGrade = "B";
    else if (average >= 70) letterGrade = "C";
    else if (average >= 60) letterGrade = "D";
    else letterGrade = "F";
    return { name, average, letterGrade, passing: average >= 60 };
  });
}

