/**
 * @param {Array<{product: string, quantity: number, price: number, category: string}>} sales
 * @returns {{totalRevenue: number, categoryTotals: Object, bestSeller: string}}
 *   totalRevenue = sum of quantity*price, categoryTotals = {category: revenue}, bestSeller = product with highest revenue
 */
function analyzeSales(sales) {

}

exercises.solution:
function analyzeSales(sales) {
  const totalRevenue = sales.reduce(function(sum, s) { return sum + s.quantity * s.price; }, 0);
  const categoryTotals = sales.reduce(function(acc, s) {
    const rev = s.quantity * s.price;
    acc[s.category] = (acc[s.category] || 0) + rev;
    return acc;
  }, {});
  const productRevenue = sales.reduce(function(acc, s) {
    const rev = s.quantity * s.price;
    acc[s.product] = (acc[s.product] || 0) + rev;
    return acc;
  }, {});
  const bestSeller = Object.keys(productRevenue).reduce(function(best, product) {
    return productRevenue[product] > productRevenue[best] ? product : best;
  });
  return { totalRevenue, categoryTotals, bestSeller };
}

