exercises.solution:
class BankAccount {
  constructor(owner, balance) {
    this.owner = owner;
    this._balance = balance || 0;
    this._history = [];
  }
  get balance() { return this._balance; }
  get history() { return this._history.slice(); }
  deposit(amount) {
    if (amount <= 0) throw new Error("Invalid amount");
    this._balance += amount;
    this._history.push({ type: "deposit", amount });
  }
  withdraw(amount) {
    if (amount <= 0) throw new Error("Invalid amount");
    if (amount > this._balance) throw new Error("Insufficient funds");
    this._balance -= amount;
    this._history.push({ type: "withdraw", amount });
  }
  transfer(amount, otherAccount) {
    this.withdraw(amount);
    otherAccount.deposit(amount);
    this._history[this._history.length - 1].type = "transfer";
  }
}

