/**
 * @param {Function} fn - The function to memoize
 * @returns {Function} A new function that caches results by JSON-stringified arguments
 *   The returned function also has a .cache property (a Map) for inspection
 */
function memoize(fn) {

}

exercises.solution:
function memoize(fn) {
  const cache = new Map();
  const memoized = function() {
    const key = JSON.stringify(Array.prototype.slice.call(arguments));
    if (cache.has(key)) {
      return cache.get(key);
    }
    const result = fn.apply(null, arguments);
    cache.set(key, result);
    return result;
  };
  memoized.cache = cache;
  return memoized;
}

