}

exercises.solution:
async function retry(asyncFn, maxRetries) {
  let lastError;
  for (let i = 0; i <= maxRetries; i++) {
    try {
      return await asyncFn();
    } catch (err) {
      lastError = err;
    }
  }
  throw new Error("Failed after " + (maxRetries + 1) + " attempts: " + lastError.message);
}

