/**
 * @param {object} pipeline - { fetch: async fn, transform: async fn, validate: async fn }
 *   fetch() returns raw data, transform(data) returns processed data, validate(data) returns validated data
 * @returns {Promise<{success: boolean, data?: *, stage?: string, error?: string}>}
 *   On success: { success: true, data: validatedResult }
 *   On failure: { success: false, stage: "fetch"|"transform"|"validate", error: message }
 */
