}

exercises.solution:
async function runPipeline(pipeline) {
  let data;
  try {
    data = await pipeline.fetch();
  } catch (err) {
    return { success: false, stage: "fetch", error: err.message };
  }
  try {
    data = await pipeline.transform(data);
  } catch (err) {
    return { success: false, stage: "transform", error: err.message };
  }
  try {
    data = await pipeline.validate(data);
  } catch (err) {
    return { success: false, stage: "validate", error: err.message };
  }
  return { success: true, data: data };
}

