function collectErrors(operations) {
  var results = [];
  var errors = [];
  for (var i = 0; i < operations.length; i++) {
    try {
      var value = operations[i]();
      results.push({ index: i, value: value });
    } catch (err) {
      errors.push({ index: i, message: err.message });
    }
  }
  return { results: results, errors: errors };
}

