function processTransaction(txn) {
  if (txn === null || typeof txn !== "object" || Array.isArray(txn)) {
    return { valid: false, errors: ["Transaction must be an object"] };
  }
  var errors = [];
  if (typeof txn.type !== "string" || (txn.type !== "credit" && txn.type !== "debit")) {
    errors.push("type must be \"credit\" or \"debit\"");
  }
  if (typeof txn.amount !== "number" || txn.amount <= 0) {
    errors.push("amount must be a positive number");
  }
  if (typeof txn.account !== "string" || txn.account.trim() === "") {
    errors.push("account must be a non-empty string");
  }
  if (typeof txn.timestamp !== "number") {
    errors.push("timestamp must be a number");
  }
  if (errors.length > 0) {
    return { valid: false, errors: errors };
  }
  return { valid: true, processed: { type: txn.type, amount: txn.amount, account: txn.account, timestamp: txn.timestamp } };
}

