function pipeline(data, steps) {
  var passed = data.slice();
  var failed = [];
  for (var s = 0; s < steps.length; s++) {
    var surviving = [];
    for (var i = 0; i < passed.length; i++) {
      try {
        passed[i] = steps[s](passed[i]);
        surviving.push(passed[i]);
      } catch (err) {
        failed.push({ item: passed[i], step: s, error: err.message });
      }
    }
    passed = surviving;
  }
  return { passed: passed, failed: failed };
}

