function checkPassword(str) {
  var length = str.length >= 8;
  var hasUpper = /[A-Z]/.test(str);
  var hasLower = /[a-z]/.test(str);
  var hasDigit = /\d/.test(str);
  var hasSpecial = /[^a-zA-Z0-9]/.test(str);
  var score = (length ? 1 : 0) + (hasUpper ? 1 : 0) + (hasLower ? 1 : 0) + (hasDigit ? 1 : 0) + (hasSpecial ? 1 : 0);
  return { length: length, hasUpper: hasUpper, hasLower: hasLower, hasDigit: hasDigit, hasSpecial: hasSpecial, score: score, strong: score === 5 };
}

