function flattenOrders(departments) {
  return departments.map(function(dept) {
    var allOrders = dept.regions.reduce(function(acc, r) {
      return acc.concat(r.orders);
    }, []);
    var total = allOrders.reduce(function(sum, o) {
      return sum + o.price * o.qty;
    }, 0);
    return { department: dept.name, orderCount: allOrders.length, total: total };
  }).sort(function(a, b) { return b.total - a.total; });
}

