function pluck(arr, path) {
  var parts = path.split(".");
  return arr.map(function(obj) {
    var val = obj;
    for (var i = 0; i < parts.length; i++) {
      if (val === undefined || val === null) return undefined;
      val = val[parts[i]];
    }
    return val;
  });
}

