exercises.solution:
function crossReference(primary, lookup, key) {
  var lookupMap = {};
  lookup.forEach(function(item) {
    lookupMap[item[key]] = item;
  });
  return primary.map(function(item) {
    var match = lookupMap[item[key]];
    var result = {};
    Object.keys(item).forEach(function(k) { result[k] = item[k]; });
    if (match) {
      Object.keys(match).forEach(function(k) {
        if (!(k in result)) result[k] = match[k];
      });
      result._matched = true;
    } else {
      result._matched = false;
    }
    return result;
  });
}

