function departmentReport(company) {
  return company.departments.map(function(dept) {
    var activeMembers = [];
    dept.teams.forEach(function(team) {
      team.members.forEach(function(m) {
        if (m.active) activeMembers.push(m);
      });
    });
    var totalSalary = activeMembers.reduce(function(sum, m) { return sum + m.salary; }, 0);
    var topEarner = null;
    if (activeMembers.length > 0) {
      topEarner = activeMembers.reduce(function(top, m) {
        return m.salary > top.salary ? m : top;
      }).name;
    }
    return {
      department: dept.name,
      teamCount: dept.teams.length,
      activeMembers: activeMembers.length,
      totalSalary: totalSalary,
      topEarner: topEarner
    };
  }).sort(function(a, b) { return b.totalSalary - a.totalSalary; });
}

