function analyzeInventory(warehouses) {
  var items = [];
  warehouses.forEach(function(w) {
    w.inventory.forEach(function(item) {
      items.push({ product: item.product, category: item.category, quantity: item.quantity, price: item.price, warehouse: w.name });
    });
  });
  var active = items.filter(function(item) { return item.quantity > 0; });
  var valued = active.map(function(item) {
    return { product: item.product, category: item.category, totalValue: item.quantity * item.price, warehouse: item.warehouse };
  });
  var groups = {};
  valued.forEach(function(item) {
    if (!groups[item.category]) groups[item.category] = [];
    groups[item.category].push(item);
  });
  return Object.keys(groups).map(function(cat) {
    var catItems = groups[cat];
    var totalValue = catItems.reduce(function(sum, i) { return sum + i.totalValue; }, 0);
    var topItem = catItems.reduce(function(top, i) { return i.totalValue > top.totalValue ? i : top; }).product;
    return { category: cat, itemCount: catItems.length, totalValue: totalValue, topItem: topItem };
  }).sort(function(a, b) { return b.totalValue - a.totalValue; });
}

