exercises.solution:
class HashMap {
  constructor(size) {
    this.size = size || 16;
    this.buckets = new Array(this.size).fill(null).map(function() { return []; });
  }
  _hash(key) {
    var hash = 0;
    for (var i = 0; i < key.length; i++) {
      hash = (hash + key.charCodeAt(i) * (i + 1)) % this.size;
    }
    return hash;
  }
  set(key, value) {
    var index = this._hash(key);
    var bucket = this.buckets[index];
    for (var i = 0; i < bucket.length; i++) {
      if (bucket[i][0] === key) {
        bucket[i][1] = value;
        return;
      }
    }
    bucket.push([key, value]);
  }
  get(key) {
    var index = this._hash(key);
    var bucket = this.buckets[index];
    for (var i = 0; i < bucket.length; i++) {
      if (bucket[i][0] === key) return bucket[i][1];
    }
    return undefined;
  }
  has(key) {
    return this.get(key) !== undefined;
  }
  delete(key) {
    var index = this._hash(key);
    var bucket = this.buckets[index];
    for (var i = 0; i < bucket.length; i++) {
      if (bucket[i][0] === key) {
        bucket.splice(i, 1);
        return true;
      }
    }
    return false;
  }
  keys() {
    var result = [];
    for (var i = 0; i < this.buckets.length; i++) {
      for (var j = 0; j < this.buckets[i].length; j++) {
        result.push(this.buckets[i][j][0]);
      }
    }
    return result;
  }
  values() {
    var result = [];
    for (var i = 0; i < this.buckets.length; i++) {
      for (var j = 0; j < this.buckets[i].length; j++) {
        result.push(this.buckets[i][j][1]);
      }
    }
    return result;
  }
}

