exercises.solution:
function bubbleSort(arr) {
  var result = arr.slice();
  var n = result.length;
  for (var i = 0; i < n - 1; i++) {
    var swapped = false;
    for (var j = 0; j < n - 1 - i; j++) {
      if (result[j] > result[j + 1]) {
        var temp = result[j];
        result[j] = result[j + 1];
        result[j + 1] = temp;
        swapped = true;
      }
    }
    if (!swapped) break;
  }
  return result;
}

