function findPairSum(arr, target) {
  var seen = {};
  for (var i = 0; i < arr.length; i++) {
    var complement = target - arr[i];
    if (seen[complement] !== undefined) {
      return [complement, arr[i]];
    }
    seen[arr[i]] = true;
  }
  return null;
}

