exercises.solution:
function maxSubarraySum(arr, k) {
  if (arr.length < k) return null;
  var windowSum = 0;
  for (var i = 0; i < k; i++) {
    windowSum += arr[i];
  }
  var maxSum = windowSum;
  for (var i = k; i < arr.length; i++) {
    windowSum = windowSum + arr[i] - arr[i - k];
    if (windowSum > maxSum) maxSum = windowSum;
  }
  return maxSum;
}

