exercises.solution:
function createEventEmitter() {
  var listeners = {};
  return {
    on: function(event, callback) {
      if (!listeners[event]) listeners[event] = [];
      if (listeners[event].indexOf(callback) === -1) {
        listeners[event].push(callback);
      }
    },
    off: function(event, callback) {
      if (!listeners[event]) return;
      listeners[event] = listeners[event].filter(function(cb) { return cb !== callback; });
    },
    emit: function(event) {
      if (!listeners[event]) return;
      var args = Array.prototype.slice.call(arguments, 1);
      listeners[event].forEach(function(cb) { cb.apply(null, args); });
    },
    listenerCount: function(event) {
      return listeners[event] ? listeners[event].length : 0;
    }
  };
}

