class Validator {
  constructor(strategy) {
    this.strategy = strategy;
  }
  setStrategy(strategy) {
    this.strategy = strategy;
  }
  validate(data) {
    return this.strategy.validate(data);
  }
  validateBatch(items) {
    var valid = [];
    var invalid = [];
    for (var i = 0; i < items.length; i++) {
      var result = this.strategy.validate(items[i]);
      if (result.valid) {
        valid.push({ item: items[i], result: result });
      } else {
        invalid.push({ item: items[i], result: result });
      }
    }
    return { valid: valid, invalid: invalid };
  }
}

var emailStrategy = {
  validate: function(str) {
    var atIndex = str.indexOf("@");
    if (atIndex === -1) return { valid: false, message: "Missing @" };
    var afterAt = str.slice(atIndex + 1);
    if (afterAt.indexOf(".") === -1) return { valid: false, message: "Missing . after @" };
    return { valid: true, message: "Valid email" };
  }
};

var numberRangeStrategy = {
  validate: function(obj) {
    if (typeof obj.value !== "number") return { valid: false, message: "Value must be a number" };
    if (obj.value < obj.min || obj.value > obj.max) return { valid: false, message: "Out of range" };
    return { valid: true, message: "In range" };
  }
};

var passwordStrategy = {
  validate: function(str) {
    if (str.length < 8) return { valid: false, message: "Too short" };
    if (!/[a-zA-Z]/.test(str)) return { valid: false, message: "Must contain a letter" };
    if (!/[0-9]/.test(str)) return { valid: false, message: "Must contain a digit" };
    return { valid: true, message: "Valid password" };
  }
};

