function createMiddlewarePipeline() {
  var middlewares = [];
  return {
    use: function(fn) {
      middlewares.push(fn);
    },
    execute: function(context) {
      var index = 0;
      function next() {
        if (index < middlewares.length) {
          var fn = middlewares[index];
          index++;
          try {
            fn(context, next);
          } catch (err) {
            context.error = err.message;
          }
        }
      }
      next();
      return context;
    }
  };
}

