exercises.solution:
function createAPI() {
  var items = [];
  var nextId = 1;
  function validate(data) {
    return data && typeof data.name === "string" && data.name.trim() !== "";
  }
  return {
    get: function(id) {
      var item = null;
      for (var i = 0; i < items.length; i++) {
        if (items[i].id === id) { item = items[i]; break; }
      }
      if (!item) return { status: 404, body: "Not Found" };
      return { status: 200, body: item };
    },
    getAll: function() {
      return { status: 200, body: items.slice() };
    },
    post: function(data) {
      if (!validate(data)) return { status: 400, body: "Validation Error" };
      var item = { id: nextId++, name: data.name };
      items.push(item);
      return { status: 201, body: item };
    },
    put: function(id, data) {
      if (!validate(data)) return { status: 400, body: "Validation Error" };
      for (var i = 0; i < items.length; i++) {
        if (items[i].id === id) {
          items[i].name = data.name;
          return { status: 200, body: items[i] };
        }
      }
      return { status: 404, body: "Not Found" };
    },
    delete: function(id) {
      for (var i = 0; i < items.length; i++) {
        if (items[i].id === id) {
          items.splice(i, 1);
          return { status: 200, body: "Deleted" };
        }
      }
      return { status: 404, body: "Not Found" };
    }
  };
}

