function createDatabase(schema) {
  var records = [];
  var nextId = 1;
  var fields = Object.keys(schema);
  function validateRecord(data) {
    for (var i = 0; i < fields.length; i++) {
      var key = fields[i];
      if (data[key] === undefined) return false;
      if (typeof data[key] !== schema[key]) return false;
    }
    return true;
  }
  function validatePartial(data) {
    var keys = Object.keys(data);
    for (var i = 0; i < keys.length; i++) {
      if (schema[keys[i]] !== undefined && typeof data[keys[i]] !== schema[keys[i]]) return false;
    }
    return true;
  }
  return {
    insert: function(record) {
      if (!validateRecord(record)) throw new Error("Validation failed");
      var stored = { _id: nextId++ };
      for (var i = 0; i < fields.length; i++) {
        stored[fields[i]] = record[fields[i]];
      }
      records.push(stored);
      return stored;
    },
    findById: function(id) {
      for (var i = 0; i < records.length; i++) {
        if (records[i]._id === id) return records[i];
      }
      return null;
    },
    find: function(query) {
      var qKeys = Object.keys(query);
      return records.filter(function(rec) {
        for (var i = 0; i < qKeys.length; i++) {
          if (rec[qKeys[i]] !== query[qKeys[i]]) return false;
        }
        return true;
      });
    },
    update: function(id, changes) {
      if (!validatePartial(changes)) throw new Error("Validation failed");
      for (var i = 0; i < records.length; i++) {
        if (records[i]._id === id) {
          var keys = Object.keys(changes);
          for (var j = 0; j < keys.length; j++) {
            if (fields.indexOf(keys[j]) !== -1) {
              records[i][keys[j]] = changes[keys[j]];
            }
          }
          return records[i];
        }
      }
      return null;
    },
    remove: function(id) {
      for (var i = 0; i < records.length; i++) {
        if (records[i]._id === id) {
          records.splice(i, 1);
          return true;
        }
      }
      return false;
    },
    count: function() {
      return records.length;
    }
  };
}

