exercises.solution:
function evaluate(expr) {
  var tokens = expr.match(/\d+|[+\-*/()]/g);
  var pos = 0;
  function parseExpr() {
    var left = parseTerm();
    while (pos < tokens.length && (tokens[pos] === "+" || tokens[pos] === "-")) {
      var op = tokens[pos]; pos++;
      var right = parseTerm();
      if (op === "+") left = left + right;
      else left = left - right;
    }
    return left;
  }
  function parseTerm() {
    var left = parseFactor();
    while (pos < tokens.length && (tokens[pos] === "*" || tokens[pos] === "/")) {
      var op = tokens[pos]; pos++;
      var right = parseFactor();
      if (op === "*") left = left * right;
      else left = left / right;
    }
    return left;
  }
  function parseFactor() {
    if (tokens[pos] === "(") {
      pos++;
      var result = parseExpr();
      pos++;
      return result;
    }
    var num = Number(tokens[pos]); pos++;
    return num;
  }
  return parseExpr();
}

