exercises.solution:
function createStore(initialState) {
  var state = {};
  var keys = Object.keys(initialState);
  for (var i = 0; i < keys.length; i++) state[keys[i]] = initialState[keys[i]];
  var subscribers = [];
  var computeds = [];
  function recompute() {
    for (var i = 0; i < computeds.length; i++) {
      state[computeds[i].name] = computeds[i].fn(state);
    }
  }
  recompute();
  return {
    getState: function() {
      var copy = {};
      var k = Object.keys(state);
      for (var i = 0; i < k.length; i++) copy[k[i]] = state[k[i]];
      return copy;
    },
    setState: function(changes) {
      var oldState = {};
      var k = Object.keys(state);
      for (var i = 0; i < k.length; i++) oldState[k[i]] = state[k[i]];
      var changeKeys = Object.keys(changes);
      for (var i = 0; i < changeKeys.length; i++) {
        state[changeKeys[i]] = changes[changeKeys[i]];
      }
      var needsRecompute = false;
      for (var i = 0; i < computeds.length; i++) {
        for (var j = 0; j < computeds[i].deps.length; j++) {
          if (changeKeys.indexOf(computeds[i].deps[j]) !== -1) {
            needsRecompute = true;
            break;
          }
        }
        if (needsRecompute) break;
      }
      if (needsRecompute) recompute();
      var newState = this.getState();
      for (var i = 0; i < subscribers.length; i++) {
        subscribers[i](newState, oldState);
      }
    },
    subscribe: function(callback) {
      subscribers.push(callback);
      return function() {
        subscribers = subscribers.filter(function(cb) { return cb !== callback; });
      };
    },
    computed: function(name, deps, fn) {
      computeds.push({ name: name, deps: deps, fn: fn });
      state[name] = fn(state);
    }
  };
}

