function createScheduler() {
  var tasks = {};
  var deps = {};
  return {
    addTask: function(name, priority, action) {
      tasks[name] = { name: name, priority: priority, action: action };
      if (!deps[name]) deps[name] = [];
    },
    addDependency: function(taskName, dependsOn) {
      if (!deps[taskName]) deps[taskName] = [];
      deps[taskName].push(dependsOn);
    },
    run: function() {
      var completed = [];
      var failed = [];
      var skipped = [];
      var completedSet = {};
      var failedSet = {};
      var sorted = Object.keys(tasks).map(function(k) { return tasks[k]; });
      sorted.sort(function(a, b) { return b.priority - a.priority; });
      var remaining = sorted.slice();
      var progress = true;
      while (remaining.length > 0 && progress) {
        progress = false;
        var next = [];
        for (var i = 0; i < remaining.length; i++) {
          var task = remaining[i];
          var taskDeps = deps[task.name] || [];
          var hasFailed = false;
          var allMet = true;
          for (var j = 0; j < taskDeps.length; j++) {
            if (failedSet[taskDeps[j]]) { hasFailed = true; break; }
            if (!completedSet[taskDeps[j]]) { allMet = false; }
          }
          if (hasFailed) {
            skipped.push(task.name);
            failedSet[task.name] = true;
            progress = true;
          } else if (allMet) {
            try {
              task.action();
              completed.push(task.name);
              completedSet[task.name] = true;
            } catch (err) {
              failed.push({ name: task.name, error: err.message });
              failedSet[task.name] = true;
            }
            progress = true;
          } else {
            next.push(task);
          }
        }
        remaining = next;
      }
      for (var i = 0; i < remaining.length; i++) {
        skipped.push(remaining[i].name);
      }
      return { completed: completed, failed: failed, skipped: skipped };
    }
  };
}

