exercises.solution:
function createPipeline() {
  var stages = [];
  return {
    addStage: function(name, fn) {
      stages.push({ name: name, fn: fn });
    },
    removeStage: function(name) {
      stages = stages.filter(function(s) { return s.name !== name; });
    },
    process: function(records) {
      var current = records.slice();
      var log = [];
      for (var i = 0; i < stages.length; i++) {
        var inputCount = current.length;
        try {
          var output = stages[i].fn(current);
          log.push({ stage: stages[i].name, inputCount: inputCount, outputCount: output.length });
          current = output;
        } catch (err) {
          log.push({ stage: stages[i].name, error: err.message });
        }
      }
      return { result: current, log: log };
    }
  };
}

