var Matrix = {
  multiply: function(a, b) {
    if (a[0].length !== b.length) throw new Error("Incompatible dimensions");
    var result = [];
    for (var i = 0; i < a.length; i++) {
      result[i] = [];
      for (var j = 0; j < b[0].length; j++) {
        var sum = 0;
        for (var k = 0; k < b.length; k++) {
          sum += a[i][k] * b[k][j];
        }
        result[i][j] = sum;
      }
    }
    return result;
  },
  transpose: function(m) {
    var result = [];
    for (var j = 0; j < m[0].length; j++) {
      result[j] = [];
      for (var i = 0; i < m.length; i++) {
        result[j][i] = m[i][j];
      }
    }
    return result;
  },
  determinant: function(m) {
    if (m.length !== m[0].length) throw new Error("Not a square matrix");
    var n = m.length;
    if (n === 1) return m[0][0];
    if (n === 2) return m[0][0] * m[1][1] - m[0][1] * m[1][0];
    var det = 0;
    for (var j = 0; j < n; j++) {
      var sub = [];
      for (var r = 1; r < n; r++) {
        var row = [];
        for (var c = 0; c < n; c++) {
          if (c !== j) row.push(m[r][c]);
        }
        sub.push(row);
      }
      var sign = j % 2 === 0 ? 1 : -1;
      det += sign * m[0][j] * Matrix.determinant(sub);
    }
    return det;
  }
};

