exercises.solution:
function createApp() {
  var middlewares = [];
  var routes = [];
  var state = {};
  return {
    use: function(fn) { middlewares.push(fn); },
    route: function(method, path, handler) {
      routes.push({ method: method.toUpperCase(), path: path, handler: handler });
    },
    setState: function(changes) {
      var keys = Object.keys(changes);
      for (var i = 0; i < keys.length; i++) state[keys[i]] = changes[keys[i]];
    },
    getState: function() {
      var copy = {};
      var keys = Object.keys(state);
      for (var i = 0; i < keys.length; i++) copy[keys[i]] = state[keys[i]];
      return copy;
    },
    handle: function(method, path) {
      var stateCopy = {};
      var sk = Object.keys(state);
      for (var i = 0; i < sk.length; i++) stateCopy[sk[i]] = state[sk[i]];
      var ctx = { method: method.toUpperCase(), path: path, state: stateCopy, body: null, status: 200 };
      try {
        var mwIndex = 0;
        function next() {
          if (mwIndex < middlewares.length) {
            var mw = middlewares[mwIndex]; mwIndex++;
            mw(ctx, next);
          }
        }
        next();
        if (ctx.body === null) {
          var matched = false;
          for (var i = 0; i < routes.length; i++) {
            if (routes[i].method === ctx.method && routes[i].path === ctx.path) {
              routes[i].handler(ctx);
              matched = true;
              break;
            }
          }
          if (!matched) {
            ctx.status = 404;
            ctx.body = "Not Found";
          }
        }
      } catch (err) {
        ctx.status = 500;
        ctx.body = err.message;
      }
      return ctx;
    }
  };
}

