exercises.solution:
function contains(obj, target) {
  for (var key in obj) {
    if (typeof obj[key] === "object" && obj[key] !== null && !Array.isArray(obj[key])) {
      if (contains(obj[key], target)) return true;
    } else {
      if (obj[key] === target) return true;
    }
  }
  return false;
}

