class DoublyLinkedList {
  constructor() {
    this.head = null;
    this.tail = null;
    this.length = 0;
  }
  push(val) {
    var node = { value: val, prev: null, next: null };
    if (!this.head) {
      this.head = node;
      this.tail = node;
    } else {
      node.prev = this.tail;
      this.tail.next = node;
      this.tail = node;
    }
    this.length++;
    return this;
  }
  pop() {
    if (!this.tail) return undefined;
    var val = this.tail.value;
    if (this.length === 1) {
      this.head = null;
      this.tail = null;
    } else {
      this.tail = this.tail.prev;
      this.tail.next = null;
    }
    this.length--;
    return val;
  }
  unshift(val) {
    var node = { value: val, prev: null, next: null };
    if (!this.head) {
      this.head = node;
      this.tail = node;
    } else {
      node.next = this.head;
      this.head.prev = node;
      this.head = node;
    }
    this.length++;
    return this;
  }
  shift() {
    if (!this.head) return undefined;
    var val = this.head.value;
    if (this.length === 1) {
      this.head = null;
      this.tail = null;
    } else {
      this.head = this.head.next;
      this.head.prev = null;
    }
    this.length--;
    return val;
  }
  get(index) {
    if (index < 0 || index >= this.length) return null;
    var current = this.head;
    for (var i = 0; i < index; i++) {
      current = current.next;
    }
    return current.value;
  }
  reverse() {
    var current = this.head;
    while (current) {
      var temp = current.prev;
      current.prev = current.next;
      current.next = temp;
      current = current.prev;
    }
    var temp2 = this.head;
    this.head = this.tail;
    this.tail = temp2;
    return this;
  }
}

