var ArrayKit = {
  chunk: function(arr, size) {
    var result = [];
    for (var i = 0; i < arr.length; i += size) {
      result.push(arr.slice(i, i + size));
    }
    return result;
  },
  zip: function() {
    var arrays = [];
    for (var i = 0; i < arguments.length; i++) arrays.push(arguments[i]);
    var maxLen = 0;
    for (var i = 0; i < arrays.length; i++) {
      if (arrays[i].length > maxLen) maxLen = arrays[i].length;
    }
    var result = [];
    for (var i = 0; i < maxLen; i++) {
      var tuple = [];
      for (var j = 0; j < arrays.length; j++) {
        tuple.push(i < arrays[j].length ? arrays[j][i] : undefined);
      }
      result.push(tuple);
    }
    return result;
  },
  difference: function(a, b) {
    return a.filter(function(x) { return b.indexOf(x) === -1; });
  },
  intersection: function(a, b) {
    return a.filter(function(x) { return b.indexOf(x) !== -1; });
  },
  flatten: function(arr) {
    var result = [];
    for (var i = 0; i < arr.length; i++) {
      if (Array.isArray(arr[i])) {
        var flat = ArrayKit.flatten(arr[i]);
        for (var j = 0; j < flat.length; j++) result.push(flat[j]);
      } else {
        result.push(arr[i]);
      }
    }
    return result;
  },
  unique: function(arr) {
    var seen = [];
    var result = [];
    for (var i = 0; i < arr.length; i++) {
      if (seen.indexOf(arr[i]) === -1) {
        seen.push(arr[i]);
        result.push(arr[i]);
      }
    }
    return result;
  }
};

