exercises.solution:
function createPipeline(data) {
  var ops = [];
  var pipeline = {
    map: function(fn) {
      ops.push({ type: "map", fn: fn });
      return pipeline;
    },
    filter: function(fn) {
      ops.push({ type: "filter", fn: fn });
      return pipeline;
    },
    take: function(n) {
      ops.push({ type: "take", n: n });
      return pipeline;
    },
    toArray: function() {
      var result = data.slice();
      for (var i = 0; i < ops.length; i++) {
        var op = ops[i];
        if (op.type === "map") {
          var mapped = [];
          for (var j = 0; j < result.length; j++) mapped.push(op.fn(result[j]));
          result = mapped;
        } else if (op.type === "filter") {
          var filtered = [];
          for (var j = 0; j < result.length; j++) {
            if (op.fn(result[j])) filtered.push(result[j]);
          }
          result = filtered;
        } else if (op.type === "take") {
          result = result.slice(0, op.n);
        }
      }
      return result;
    }
  };
  return pipeline;
}

