  this.subject = subject;
}
function Department(name) {
  this.name = name;
  this._teachers = [];
  this._students = [];
}
Department.prototype.addTeacher = function(teacher) { this._teachers.push(teacher); };
Department.prototype.addStudent = function(student) { this._students.push(student); };
Department.prototype.getTeachers = function() { return this._teachers.slice(); };
Department.prototype.getStudents = function() { return this._students.slice(); };
function School(name) {
  this.name = name;
  this._departments = [];
}
School.prototype.addDepartment = function(dept) { this._departments.push(dept); };
School.prototype.getDepartment = function(name) {
  for (var i = 0; i < this._departments.length; i++) {
    if (this._departments[i].name === name) return this._departments[i];
  }
  return null;
};
School.prototype.getStats = function() {
  var teachers = 0, students = 0;
  for (var i = 0; i < this._departments.length; i++) {
    teachers += this._departments[i].getTeachers().length;
    students += this._departments[i].getStudents().length;
  }
  return { departments: this._departments.length, teachers: teachers, students: students };
};

