function Book(title, author) {
  this.title = title;
  this.author = author;
  this.borrowedBy = null;
}
function Member(name) {
  this.name = name;
  this._borrowed = [];
}
Member.prototype.borrow = function(book) {
  if (book.borrowedBy !== null) return false;
  book.borrowedBy = this.name;
  this._borrowed.push(book);
  return true;
};
Member.prototype.return = function(book) {
  if (book.borrowedBy !== this.name) return false;
  book.borrowedBy = null;
  this._borrowed = this._borrowed.filter(function(b) { return b !== book; });
  return true;
};
Member.prototype.getBorrowed = function() { return this._borrowed.slice(); };
function Library(name) {
  this.name = name;
  this._books = [];
  this._members = [];
}
Library.prototype.addBook = function(book) { this._books.push(book); };
Library.prototype.addMember = function(member) { this._members.push(member); };
Library.prototype.search = function(query) {
  var q = query.toLowerCase();
  return this._books.filter(function(b) { return b.title.toLowerCase().indexOf(q) !== -1; });
};
Library.prototype.getAvailableBooks = function() {
  return this._books.filter(function(b) { return b.borrowedBy === null; });
};

