function createTestFramework() {
  var suites = [];
  var currentSuite = null;
  var framework = {
    describe: function(name, fn) {
      var parent = currentSuite;
      var suite = { name: name, parent: parent, tests: [], children: [] };
      if (parent) {
        parent.children.push(suite);
      } else {
        suites.push(suite);
      }
      currentSuite = suite;
      fn();
      currentSuite = parent;
    },
    it: function(name, fn) {
      if (currentSuite) {
        currentSuite.tests.push({ name: name, fn: fn });
      } else {
        suites.push({ name: null, tests: [{ name: name, fn: fn }], children: [] });
      }
    },
    expect: function(value) {
      return {
        toBe: function(expected) {
          if (value !== expected) throw new Error("Expected " + JSON.stringify(expected) + " but got " + JSON.stringify(value));
        },
        toEqual: function(expected) {
          if (JSON.stringify(value) !== JSON.stringify(expected)) throw new Error("Expected " + JSON.stringify(expected) + " but got " + JSON.stringify(value));
        },
        toThrow: function() {
          var threw = false;
          try { value(); } catch(e) { threw = true; }
          if (!threw) throw new Error("Expected function to throw");
        }
      };
    },
    run: function() {
      var passed = 0;
      var failed = 0;
      var results = [];
      function getPath(suite) {
        var parts = [];
        var s = suite;
        while (s && s.name) {
          parts.unshift(s.name);
          s = s.parent;
        }
        return parts;
      }
      function runSuite(suite) {
        var path = getPath(suite);
        for (var i = 0; i < suite.tests.length; i++) {
          var test = suite.tests[i];
          var fullName = path.concat([test.name]).join(" > ");
          try {
            test.fn();
            passed++;
            results.push({ name: fullName, passed: true, error: null });
          } catch(e) {
            failed++;
            results.push({ name: fullName, passed: false, error: e.message });
          }
        }
        for (var i = 0; i < suite.children.length; i++) {
          runSuite(suite.children[i]);
        }
      }
      for (var i = 0; i < suites.length; i++) {
        runSuite(suites[i]);
      }
      return { passed: passed, failed: failed, results: results };
    }
  };
  return framework;
}

