function StatusEffect(name, duration, apply) {
  this.name = name;
  this.duration = duration;
  this.apply = apply;
}
function Fighter(name, hp, attack) {
  this.name = name;
  this.hp = hp;
  this.maxHp = hp;
  this.attack = attack;
  this.effects = [];
}
Fighter.prototype.isAlive = function() { return this.hp > 0; };
Fighter.prototype.takeDamage = function(amount) {
  this.hp -= amount;
  if (this.hp < 0) this.hp = 0;
};
Fighter.prototype.applyEffect = function(effect) {
  this.effects.push({ name: effect.name, duration: effect.duration, apply: effect.apply });
};
Fighter.prototype.processEffects = function() {
  var remaining = [];
  for (var i = 0; i < this.effects.length; i++) {
    var eff = this.effects[i];
    eff.apply(this);
    eff.duration--;
    if (eff.duration > 0) remaining.push(eff);
  }
  this.effects = remaining;
};
function Battle(fighter1, fighter2) {
  this.fighter1 = fighter1;
  this.fighter2 = fighter2;
}
Battle.prototype.playRound = function() {
  var log = [];
  if (this.fighter1.isAlive()) {
    this.fighter1.processEffects();
    if (this.fighter1.isAlive()) {
      var dmg1 = this.fighter1.attack;
      this.fighter2.takeDamage(dmg1);
      log.push({ attacker: this.fighter1.name, defender: this.fighter2.name, damage: dmg1 });
    }
  }
  if (this.fighter2.isAlive()) {
    this.fighter2.processEffects();
    if (this.fighter2.isAlive()) {
      var dmg2 = this.fighter2.attack;
      this.fighter1.takeDamage(dmg2);
      log.push({ attacker: this.fighter2.name, defender: this.fighter1.name, damage: dmg2 });
    }
  }
  return log;
};
Battle.prototype.getWinner = function() {
  if (!this.fighter1.isAlive() && !this.fighter2.isAlive()) return null;
  if (!this.fighter1.isAlive()) return this.fighter2;
  if (!this.fighter2.isAlive()) return this.fighter1;
  return null;
};

