function Post(author, content) {
  this.author = author;
  this.content = content;
  this.likes = 0;
  this.likedBy = [];
  this.comments = [];
}
Post.prototype.getScore = function() { return this.likes + this.comments.length; };
function User(name) {
  this.name = name;
}
User.prototype.like = function(post) {
  if (post.likedBy.indexOf(this.name) !== -1) return false;
  post.likedBy.push(this.name);
  post.likes++;
  return true;
};
User.prototype.comment = function(post, text) {
  post.comments.push({ author: this.name, text: text });
};
function SocialFeed() {
  this._users = [];
  this._posts = [];
}
SocialFeed.prototype.addUser = function(user) { this._users.push(user); };
SocialFeed.prototype.createPost = function(userName, content) {
  var post = new Post(userName, content);
  this._posts.push(post);
  return post;
};
SocialFeed.prototype.getFeed = function() {
  return this._posts.slice().sort(function(a, b) { return b.getScore() - a.getScore(); });
};

