exercises.solution:
function matchPattern(pattern, text) {
  var hasStart = pattern.charAt(0) === "^";
  var hasEnd = pattern.charAt(pattern.length - 1) === "$";
  var pat = pattern;
  if (hasStart) pat = pat.slice(1);
  if (hasEnd) pat = pat.slice(0, -1);
  var tokens = tokenize(pat);
  if (hasStart && hasEnd) {
    return matchHere(tokens, 0, text, 0, text.length);
  } else if (hasStart) {
    for (var end = 0; end <= text.length; end++) {
      if (matchHere(tokens, 0, text, 0, end)) return true;
    }
    return false;
  } else if (hasEnd) {
    for (var start = 0; start <= text.length; start++) {
      if (matchHere(tokens, 0, text, start, text.length)) return true;
    }
    return false;
  } else {
    for (var start = 0; start <= text.length; start++) {
      for (var end = start; end <= text.length; end++) {
        if (matchHere(tokens, 0, text, start, end)) return true;
      }
    }
    return false;
  }
  function tokenize(p) {
    var toks = [];
    var i = 0;
    while (i < p.length) {
      if (p[i] === "[") {
        var j = p.indexOf("]", i);
        var chars = p.slice(i + 1, j);
        i = j + 1;
        var quant = null;
        if (i < p.length && (p[i] === "*" || p[i] === "+" || p[i] === "?")) { quant = p[i]; i++; }
        toks.push({ type: "class", chars: chars, quant: quant });
      } else if (p[i] === ".") {
        i++;
        var quant = null;
        if (i < p.length && (p[i] === "*" || p[i] === "+" || p[i] === "?")) { quant = p[i]; i++; }
        toks.push({ type: "dot", quant: quant });
      } else {
        var ch = p[i]; i++;
        var quant = null;
        if (i < p.length && (p[i] === "*" || p[i] === "+" || p[i] === "?")) { quant = p[i]; i++; }
        toks.push({ type: "lit", ch: ch, quant: quant });
      }
    }
    return toks;
  }
  function charMatches(tok, ch) {
    if (tok.type === "dot") return true;
    if (tok.type === "lit") return tok.ch === ch;
    if (tok.type === "class") return tok.chars.indexOf(ch) !== -1;
    return false;
  }
  function matchHere(toks, ti, txt, si, end) {
    if (ti === toks.length) return si === end;
    var tok = toks[ti];
    if (tok.quant === "*") {
      for (var count = 0; si + count <= end; count++) {
        if (count > 0 && !charMatches(tok, txt[si + count - 1])) break;
        if (matchHere(toks, ti + 1, txt, si + count, end)) return true;
      }
      return false;
    } else if (tok.quant === "+") {
      for (var count = 1; si + count <= end; count++) {
        if (!charMatches(tok, txt[si + count - 1])) break;
        if (matchHere(toks, ti + 1, txt, si + count, end)) return true;
      }
      return false;
    } else if (tok.quant === "?") {
      if (matchHere(toks, ti + 1, txt, si, end)) return true;
      if (si < end && charMatches(tok, txt[si]) && matchHere(toks, ti + 1, txt, si + 1, end)) return true;
      return false;
    } else {
      if (si >= end) return false;
      if (!charMatches(tok, txt[si])) return false;
      return matchHere(toks, ti + 1, txt, si + 1, end);
    }
  }
}

