  const addOnce = once(() => ++count);
  addOnce(); addOnce(); addOnce();
  count → 1  (original only ran once)

exercises.solution:
function once(fn) {
  let called = false;
  let result;
  return function() {
    if (!called) {
      called = true;
      result = fn();
    }
    return result;
  };
}

