exercises.instructions:
Write a function `parseURL(urlString)` that takes a URL and returns an object:
```js
{ protocol, host, path, query }
```

- `protocol` — e.g. `'https'` (without the `://`)
- `host` — e.g. `'example.com'`
- `path` — e.g. `'/products/123'` (or `'/'` if none)
- `query` — an object of key-value pairs (or `{}` if no query string)

```js
parseURL('https://example.com/search?q=hello&page=2')
// => { protocol: 'https', host: 'example.com', path: '/search', query: { q: 'hello', page: '2' } }

parseURL('http://site.com')
// => { protocol: 'http', host: 'site.com', path: '/', query: {} }
```

exercises.starterCode:
function parseURL(urlString) {
  // your code here
}

exercises.solution:
function parseURL(urlString) {
  const protoEnd = urlString.indexOf('://');
  const protocol = urlString.substring(0, protoEnd);
  const rest = urlString.substring(protoEnd + 3);
  const pathStart = rest.indexOf('/');
  let host, pathAndQuery;
  if (pathStart === -1) {
    host = rest;
    pathAndQuery = '/';
  } else {
    host = rest.substring(0, pathStart);
    pathAndQuery = rest.substring(pathStart);
  }
  const qIdx = pathAndQuery.indexOf('?');
  let urlPath, query = {};
  if (qIdx === -1) {
    urlPath = pathAndQuery;
  } else {
    urlPath = pathAndQuery.substring(0, qIdx);
    const qs = pathAndQuery.substring(qIdx + 1);
    qs.split('&').forEach(function(pair) {
      const parts = pair.split('=');
      query[parts[0]] = parts[1] || '';
    });
  }
  return { protocol: protocol, host: host, path: urlPath, query: query };
}

