  // use nested loops: outer picks first element, inner picks second
}

exercises.solution:
function findPairs(nums, target) {
  const pairs = [];
  for (let i = 0; i < nums.length; i++) {
    for (let j = i + 1; j < nums.length; j++) {
      if (nums[i] + nums[j] === target) {
        pairs.push([nums[i], nums[j]]);
      }
    }
  }
  return pairs;
}

