exercises.starterCode:
function createSpy(fn) {
  // your code here
}

exercises.solution:
function createSpy(fn) {
  const calls = [];
  return {
    fn: function(...args) {
      calls.push(args);
      return fn(...args);
    },
    calls: calls,
    callCount: function() { return calls.length; },
    lastArgs: function() { return calls.length ? calls[calls.length - 1] : undefined; }
  };
}

