exercises.starterCode:
function throttle(fn, delay) {
  // your code here
}

exercises.solution:
function throttle(fn, delay) {
  let lastCall = 0;
  return function(...args) {
    const now = Date.now();
    if (now - lastCall >= delay) {
      lastCall = now;
      return fn.apply(this, args);
    }
  };
}

