exercises.instructions:
Write a function `createRouter()` that returns an object with:
- `addRoute(path, handler)` — registers a handler for a path string
- `match(url)` — finds the matching route and calls its handler. Returns the handler's return value, or `null` if no match.

Paths are exact strings (no pattern matching needed).

```js
const router = createRouter();
router.addRoute('/home', () => 'Home Page');
router.addRoute('/about', () => 'About Page');
router.addRoute('/users', (q) => 'Users: ' + q);

router.match('/home')     // => 'Home Page'
router.match('/about')    // => 'About Page'
router.match('/nope')     // => null
```

exercises.starterCode:
function createRouter() {
  // your code here
}

exercises.solution:
function createRouter() {
  const routes = {};
  return {
    addRoute: function(path, handler) {
      routes[path] = handler;
    },
    match: function(url) {
      if (routes.hasOwnProperty(url)) {
        return routes[url]();
      }
      return null;
    }
  };
}

