exercises.starterCode:
function curry(fn) {
  // return a function that works both ways:
  // called with 2 args → run fn immediately
  // called with 1 arg  → return a function waiting for the second
}

exercises.solution:
function curry(fn) {
  return function(a, b) {
    if (b !== undefined) {
      return fn(a, b);
    }
    return function(b) {
      return fn(a, b);
    };
  };
}

