exercises.solution:
class EventEmitter {
  constructor() {
    this.events = {};
  }

  on(eventName, listener) {
    if (!this.events[eventName]) this.events[eventName] = [];
    this.events[eventName].push(listener);
  }

  emit(eventName, ...args) {
    if (!this.events[eventName] || this.events[eventName].length === 0) return false;
    this.events[eventName].forEach(listener => listener(...args));
    return true;
  }

  off(eventName, listener) {
    if (!this.events[eventName]) return;
    this.events[eventName] = this.events[eventName].filter(l => l !== listener);
  }

  listenerCount(eventName) {
    if (!this.events[eventName]) return 0;
    return this.events[eventName].length;
  }
}

exercises.instructions:
Write a function `createTestRunner()` that returns an object with:
- `describe(suiteName, callback)` — groups tests under a suite name
- `it(testName, callback)` — defines a test; callback should throw on failure
- `run()` — returns an array of results:
  ```js
  { suite: 'suiteName', test: 'testName', pass: true/false, error: null/string }
  ```

```js
const t = createTestRunner();
t.describe('Math', () => {
  t.it('adds', () => { if (1+1 !== 2) throw new Error('bad'); });
  t.it('fails', () => { throw new Error('oops'); });
});
t.run();
// => [
//   { suite: 'Math', test: 'adds', pass: true, error: null },
//   { suite: 'Math', test: 'fails', pass: false, error: 'oops' }
// ]
```

exercises.starterCode:
function createTestRunner() {
  // your code here
}

exercises.solution:
function createTestRunner() {
  const suites = [];
  let currentSuite = null;
  return {
    describe: function(name, cb) {
      currentSuite = { name: name, tests: [] };
      suites.push(currentSuite);
      cb();
      currentSuite = null;
    },
    it: function(name, cb) {
      if (currentSuite) {
        currentSuite.tests.push({ name: name, cb: cb });
      }
    },
    run: function() {
      const results = [];
      for (const suite of suites) {
        for (const test of suite.tests) {
          try {
            test.cb();
            results.push({ suite: suite.name, test: test.name, pass: true, error: null });
          } catch (e) {
            results.push({ suite: suite.name, test: test.name, pass: false, error: e.message || String(e) });
          }
        }
      }
      return results;
    }
  };
}

exercises.testRunner:
(code) => {
  const fn = new Function(code + '; return createTestRunner;')();
  const t = fn();
  t.describe('Math', function() {
    t.it('1+1=2', function() { if (1+1 !== 2) throw new Error('bad math'); });
    t.it('fails', function() { throw new Error('oops'); });
  });
  t.describe('Strings', function() {
    t.it('concat', function() { if ('a'+'b' !== 'ab') throw new Error('bad'); });
  });
  const results = t.run();
  const r1 = results.length === 3;
  const r2 = results[0] && results[0].pass === true && results[0].suite === 'Math';
  const r3 = results[1] && results[1].pass === false && results[1].error === 'oops';
  const r4 = results[2] && results[2].suite === 'Strings' && results[2].pass === true;
  return [
    { pass: r1, description: 'Collects 3 test results', got: 'count: ' + results.length },
    { pass: r2, description: 'Passing test has pass:true and suite name', got: JSON.stringify(results[0]) },
    { pass: r3, description: 'Failing test has pass:false and error message', got: JSON.stringify(results[1]) },
    { pass: r4, description: 'Multiple suites tracked separately', got: JSON.stringify(results[2]) }
  ];
}

exercises.starterCode:
class RequestCache {
  constructor(defaultTTL) {
    // your code here
  }

  set(url, data, ttl) {}
  get(url) {}
  has(url) {}
  clear() {}
  get size() {}
}

exercises.solution:
class RequestCache {
  constructor(defaultTTL) {
    this._defaultTTL = defaultTTL;
    this._cache = {};
  }

  set(url, data, ttl) {
    this._cache[url] = {
      data: data,
      expiry: Date.now() + (ttl !== undefined ? ttl : this._defaultTTL)
    };
  }

  get(url) {
    const entry = this._cache[url];
    if (!entry) return null;
    if (Date.now() > entry.expiry) {
      delete this._cache[url];
      return null;
    }
    return entry.data;
  }

  has(url) {
    return this.get(url) !== null;
  }

  clear() {
    this._cache = {};
  }

  get size() {
    const now = Date.now();
    let count = 0;
    for (const url in this._cache) {
      if (this._cache[url].expiry > now) count++;
    }
    return count;
  }
}

exercises.testRunner:
(code) => {
  const RC = new Function(code + '; return RequestCache;')();
  const origNow = Date.now;
  let fakeTime = origNow.call(Date);
  Date.now = function() { return fakeTime; };
  try {
    const c = new RC(100);
    c.set('/a', 'dataA');
    const r1 = c.get('/a') === 'dataA' && c.has('/a') === true;
    fakeTime += 50;
    const r2 = c.get('/a') === 'dataA';
    fakeTime += 60;
    const r3 = c.get('/a') === null && c.has('/a') === false;
    fakeTime = origNow.call(Date);
    const c2 = new RC(1000);
    c2.set('/x', 'x1');
    c2.set('/y', 'y1');
    const r4sz = c2.size === 2;
    c2.clear();
    const r4 = c2.size === 0;
    Date.now = origNow;
    return [
      { pass: r1, description: 'set/get/has works for cached data', got: String(r1) },
      { pass: r2, description: 'Data available before TTL expires', got: String(r2) },
      { pass: r3, description: 'Data expires after TTL', got: String(r3) },
      { pass: r4sz && r4, description: 'size counts entries, clear removes all', got: 'size before:2 after:' + c2.size }
    ];
  } finally {
    Date.now = origNow;
  }
}

