.form-input {
  padding: 10px 12px;
  border: 1px solid #94a3b8;
  border-radius: 6px;
  font-size: 16px;
  width: 100%;
  transition: border-color 0.2s ease;
  box-sizing: border-box;
}

.form-input:focus {
  border-color: #3b82f6;
  outline: none;
}

.form-select {
  padding: 10px 12px;
  border: 1px solid #94a3b8;
  border-radius: 6px;
  font-size: 16px;
  width: 100%;
}

.form-btn {
  background-color: #3b82f6;
  color: white;
  padding: 10px 24px;
  border: none;
  border-radius: 6px;
  cursor: pointer;
}

.data-table {
  width: 100%;
  border-collapse: collapse;
  border-radius: 8px;
  overflow: hidden;
}

.data-table th,
.data-table td {
  padding: 12px 16px;
  text-align: left;
  border-bottom: 1px solid #e2e8f0;
}

.data-table th {
  background-color: #1e293b;
  color: white;
  font-weight: 600;
}

.data-table tr:nth-child(even) {
  background-color: #f8fafc;
}

.data-table tr:hover {
  background-color: #e2e8f0;
}

.overlay {
  position: fixed;
  top: 0;
  left: 0;
  width: 100%;
  height: 100%;
  background-color: rgba(0, 0, 0, 0.5);
  z-index: 100;
  display: flex;
  justify-content: center;
  align-items: center;
}

.modal {
  background-color: white;
  padding: 32px;
  border-radius: 12px;
  max-width: 500px;
  width: 90%;
  box-shadow: 0 20px 60px rgba(0, 0, 0, 0.3);
}

.filter-img {
  transition: filter 0.3s ease;
}

.filter-img:hover {
  filter: none;
}

.blur-img {
  filter: blur(4px);
}

.grayscale-img {
  filter: grayscale(100%);
}

.bright-img {
  filter: brightness(1.3);
}

.sepia-img {
  filter: sepia(80%);
}

.combined-img {
  filter: contrast(1.2) saturate(1.5);
}

.card-container {
  display: grid;
  grid-template-columns: 1fr;
  gap: 20px;
  padding: 20px;
}

.resp-card {
  padding: 20px;
  border: 1px solid #e2e8f0;
  border-radius: 8px;
}

@media (min-width: 640px) {
  .card-container {
    grid-template-columns: repeat(2, 1fr);
  }
}

@media (min-width: 1024px) {
  .card-container {
    grid-template-columns: repeat(3, 1fr);
  }
}
